import{_ as s}from"./chunks/1fbcb48a9e8a46bcb5eb11c7bf7bb471~tplv-k3u1fbpfcp-watermark.Dal4lUk3.js";import{_ as a,o as i,c as n,a4 as p}from"./chunks/framework.CW-6O5Zu.js";const t="/assets/29ef6c67f7774fc9ac80701f3076d0d8~tplv-k3u1fbpfcp-watermark.DF1uTtlm.jpg",o="/assets/c11efd0629e049df8620f884a993b0d9~tplv-k3u1fbpfcp-watermark.DM2RkHTg.jpg",l="/assets/40b1d3136a1b453eaeda912932b6b9e6~tplv-k3u1fbpfcp-watermark.Clt1H7S2.jpg",c="/assets/4a4c9bac65464eda8533db9f8d32c07b~tplv-k3u1fbpfcp-watermark.DiC39q5S.jpg",d="/assets/e111c11458ff4a1ea205c78d41685bca~tplv-k3u1fbpfcp-watermark.DYiEcHTh.jpg",r="/assets/228c849b88004b79a1472de99c8e1b89~tplv-k3u1fbpfcp-watermark.Cz6_ngBV.jpg",h="/assets/900ea08f589c4522ba71703c0862282a~tplv-k3u1fbpfcp-watermark.BFwCWBCX.jpg",k="/assets/d768099f3d964afc817fb0f65a69f177~tplv-k3u1fbpfcp-watermark.DYFq-64C.jpg",g="/assets/74a500f04cee4c459b6b89d84805ee35~tplv-k3u1fbpfcp-watermark.BHeXhPt3.jpg",D=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/courses/Electron + React 从 0 到 1 实现简历平台实战/25-打包篇-Electron打包体积优化.md","filePath":"knowledge/courses/Electron + React 从 0 到 1 实现简历平台实战/25-打包篇-Electron打包体积优化.md","lastUpdated":1776407975000}'),m={name:"knowledge/courses/Electron + React 从 0 到 1 实现简历平台实战/25-打包篇-Electron打包体积优化.md"};function f(u,e,b,_,B,E){return i(),n("div",null,[...e[0]||(e[0]=[p('<h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>应用构建生成安装包，窃喜，欲分享，微信至张三，张三曰：“入夜，来吾陋室，共享之”，夜深，手挎电脑，进寝室，颤巍双手点鼠标，发送，少倾，啪的一声，张三怒而站起，曰：“汝为何之大！”</p><p>多大？来看看我们的应用程序大小。<code>219M</code>，想一想，我们也没写什么代码，咋就这么大了？</p><p><img src="'+t+'" alt="image.png" loading="lazy"></p><p>我们右键应用程序，选中“显示包内容”，点击进入到 <code>Contents</code>，可以看到一些文件夹。</p><p><img src="'+o+'" alt="image.png" loading="lazy"></p><p>比如这个 <code>Frameworks</code> 里面放的是 v8 引擎和 chromium 内核，我们看看它有多大。</p><p><img src="'+l+'" alt="image.png" loading="lazy"></p><p>单单这个东西就占了 178M，另外的 40M 左右大小在哪呢？我们看看 <code>Contents/Resources</code> 文件夹下，有一个叫做 <code>app.asar</code> 的玩意。</p><p><img src="'+c+'" alt="image.png" loading="lazy"></p><p>哦豁，这是个什么东西，大小居然 40M，这个 asar 是个啥玩意？我们可以从<a href="https://fileinfo.com/extension/asar" target="_blank" rel="noreferrer">文档</a>中看到说明</p><blockquote><p>An ASAR file is an archive used to package source code for an application using Electron, an open source library used to build cross-platform programs. It is saved in a format similar to <a href="https://fileinfo.com/extension/tar" target="_blank" rel="noreferrer">.TAR</a> archives where files contained in the archive, such as <a href="https://fileinfo.com/extension/html" target="_blank" rel="noreferrer">.HTML</a>, <a href="https://fileinfo.com/extension/js" target="_blank" rel="noreferrer">.JS</a>, and <a href="https://fileinfo.com/extension/css" target="_blank" rel="noreferrer">.CSS</a> files, are concatenated together without using compression.</p></blockquote><p>我们可以来解压一下 <code>app.asar</code>，网上搜对应文章就 OK 了。下面我们跟着阿宽解压一波</p><ol><li>首先安装</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>npm install -g asar</span></span></code></pre></div><ol start="2"><li>进入到 <code>Contents/Resources</code> 文件夹内进行解压，下面解压到该文件夹下的 app 文件夹</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>asar extract app.asar ./app</span></span></code></pre></div><p>你就会看到有一个 <code>app</code> 文件夹，点进去看一看</p><p><img src="'+d+'" alt="image.png" loading="lazy"></p><h2 id="优化方向" tabindex="-1">优化方向 <a class="header-anchor" href="#优化方向" aria-label="Permalink to &quot;优化方向&quot;">​</a></h2><p>先来捋一捋，我们整个应用打包出来的文件夹是这样的</p><p><img src="'+r+'" alt="image.png" loading="lazy"></p><p>关于 <code>Frameworks</code> 我们是操作不了了，里面放的是 v8 引擎和 chromium 内核，我们只能想办法优化 <code>Resources</code>，在 Resources 中好像很多文件夹都比较小，并且是默认生成的，正所谓“不做作就不会死”，改出了问题怎么办（关键你也不知道怎么改），所以说我们还是动熟悉的那块。</p><p>那么哪一块我们熟悉呢？<code>app.asar</code>解压后的 <code>dist</code> 和 <code>node_modules</code>，上面看到了，40M 里，node_modules 占了大头，所以我们要做的是我们的应用能否不打包 <code>node_modules</code> 文件夹，或者是让打包的东西尽可能少？</p><h2 id="打包优化" tabindex="-1">打包优化 <a class="header-anchor" href="#打包优化" aria-label="Permalink to &quot;打包优化&quot;">​</a></h2><p>electron 在打包过程中，会读取 <code>package.json</code> 中的 <code>dependencies</code> 依赖，将其依赖 <code>“copy”</code> 一份放在 <code>Resources/app.asar</code> 中，也就是我们压缩之后的代码包。</p><p><strong>故此，想要减小包体积大小，就要减小 <code>node_modules</code> 的大小，想减小 <code>node_modules</code> 的大小，就要做到 <code>dependencise</code> 依赖尽可能少，想减少 <code>dependencise</code> 依赖，就要把没必要的包放在 <code>devDependencies</code>。</strong></p><p>方法告诉你了，赶紧动手试试吧！因为前面阿宽已经区分过了，等价于已经优化过一轮了。</p><blockquote><p>你可以皮一下，把 package.json 中的 devDependencise 包都放在 dependencise，然后打个包看看体积多大，经过对比，验证结论。</p></blockquote><h2 id="知识点延伸" tabindex="-1">知识点延伸 <a class="header-anchor" href="#知识点延伸" aria-label="Permalink to &quot;知识点延伸&quot;">​</a></h2><h3 id="_1-关于-dependencies-与-devdependencies" tabindex="-1">1. 关于 dependencies 与 devDependencies <a class="header-anchor" href="#_1-关于-dependencies-与-devdependencies" aria-label="Permalink to &quot;1. 关于 dependencies 与 devDependencies&quot;">​</a></h3><ul><li>dependencies 是产生环境下的依赖，比如说 Vue、React 等</li><li>devDependencies 是开发环境下的依赖，比如 Webpack、ESLint、Babel 等</li></ul><p>可能这么讲小伙伴们还是不怎么能区分，这么说吧。我写了一个 React UI 组件包，其中依赖了 AntDesign，那我需要将 AntDesign 和 React 放在 dependencies 中。</p><p>再比如说，我们项目中用到了 Redux，但是 Redux 的 devDependencies 里面有 jest、rxjs 等，在我们安装 Redux 时，我们是不会把 jest、rxjs 拉下来的（也就是 node_modules 里是不会有 jest、rxjs）</p><p><img src="'+s+`" alt="image.png" loading="lazy"></p><p>一般我们开发过程中，会在项目中安装 webpack、webpack-dev-server、babel、eslint 的等工具库，或者是用于单元测试的 jest 库，这些依赖库都只是在我们项目开发过程中使用，应该写在 devDependencies 里。如果说我们依赖乱写，例如开发依赖放在生产，生产依赖放在开发，这会出现什么问题？</p><p>以 <a href="https://github.com/SugarTurboS/rc-redux-model/blob/master/package.json" target="_blank" rel="noreferrer">rc-redux-model</a>为例，我们可以看到它的依赖非常的少。这是一个 npm 包。当我们执行 <code>npm install rc-redux-model</code> 时，此时会将 dependencies 的依赖都安装，不会安装 devDependencies 里的依赖库。</p><p>但如果是通过克隆仓库项目代码，如 <code>git clone https://github.com/SugarTurboS/rc-redux-model</code>，然后再 <code>npm instal</code>，这时候会将 dependencies 和 devDependencies 里的依赖库都安装。</p><h3 id="_2-devdependencise-包依赖会被打进去吗" tabindex="-1">2. devDependencise 包依赖会被打进去吗？ <a class="header-anchor" href="#_2-devdependencise-包依赖会被打进去吗" aria-label="Permalink to &quot;2. devDependencise 包依赖会被打进去吗？&quot;">​</a></h3><p>一开始我也有疑惑，如上所述的，electron 打包只会将 dependencise 依赖打进去，那假设我不小心把 <code>lodash</code>、<code>axios</code> 放在了 devDependencise 里。</p><p>结果是什么：electron 打包后的 <code>Resources/app.asar</code> 解压后，node_modules 是找不到 <code>lodash</code>、<code>axios</code> 的！小伙伴们能理解吧？那么我不禁思考，我代码里肯定用到了 axios、lodash，为什么它不报错，为什么能正常运行？</p><p>于是我做了一个实验。新增一个空项目，然后写一份 package.json，安装一下，接着新增一个 a.js，编写下面代码，看看打包之后的内容。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes one-dark-pro material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7F848E;--shiki-light-font-style:italic;--shiki-dark:#676E95;--shiki-dark-font-style:italic;">// 第一步：创建文件夹</span></span>
<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">mkdir</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;"> test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#7F848E;--shiki-light-font-style:italic;--shiki-dark:#676E95;--shiki-dark-font-style:italic;">// 第二步：进入文件夹</span></span>
<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">cd</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;"> test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#7F848E;--shiki-light-font-style:italic;--shiki-dark:#676E95;--shiki-dark-font-style:italic;">// 第三步：新增 package.json</span></span>
<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">touch</span><span style="--shiki-light:#E5C07B;--shiki-dark:#BABED8;"> package</span><span style="--shiki-light:#ABB2BF;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#7F848E;--shiki-light-font-style:italic;--shiki-dark:#676E95;--shiki-dark-font-style:italic;">// 第四步：编写 package.json，按照下面图片写一下就好了</span></span>
<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">vim</span><span style="--shiki-light:#E5C07B;--shiki-dark:#BABED8;"> package</span><span style="--shiki-light:#ABB2BF;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#7F848E;--shiki-light-font-style:italic;--shiki-dark:#676E95;--shiki-dark-font-style:italic;">// 第五步：新增 a.js</span></span>
<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">touch</span><span style="--shiki-light:#E5C07B;--shiki-dark:#BABED8;"> a</span><span style="--shiki-light:#ABB2BF;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">js</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#7F848E;--shiki-light-font-style:italic;--shiki-dark:#676E95;--shiki-dark-font-style:italic;">// 第六步：编写 a.js，按照下面图片写一下就好了</span></span>
<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">vim</span><span style="--shiki-light:#E5C07B;--shiki-dark:#BABED8;"> a</span><span style="--shiki-light:#ABB2BF;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">js</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#7F848E;--shiki-light-font-style:italic;--shiki-dark:#676E95;--shiki-dark-font-style:italic;">// 第七步：打包</span></span>
<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">npx</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;"> webpack</span><span style="--shiki-light:#E5C07B;--shiki-dark:#BABED8;"> a</span><span style="--shiki-light:#ABB2BF;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#E06C75;--shiki-dark:#BABED8;">js</span></span></code></pre></div><p>首先我们先来测试，<code>devDependencise</code> 依赖中有个叫 lodash 的库</p><p><img src="`+h+'" alt="image.png" loading="lazy"></p><p>再来测试一下，<code>dependencise</code> 依赖中有个叫 axios 的库</p><p><img src="'+k+'" alt="image.png" loading="lazy"></p><p>在测试一下，如果是插件类的 <code>devDependencise</code>，是不是也会打进去呢？试试 <code>webpack-merge</code></p><p><img src="'+g+'" alt="image.png" loading="lazy"></p><p><strong>结论：我个人认为，无论是 <code>devDependencise</code> 还是 <code>dependencise</code>，实际上都会把这些包打进 js 中。对于 web 应用项目来讲，依赖写在哪不是很重要，说实在话项目中多多少少还是会有一些依赖是处于混用状态。但这是个人主观意识，说白了就是有没有代码洁癖，是不是严格要求写依赖。</strong></p><blockquote><p>对于 web 应用来讲，不是很重要，但对于开发第三方包来讲，一定要严格区分，正如我前面所说的，第三方包 <code>npm install</code> 时，只会安装 <code>dependencise</code> 的依赖。同时对于 electron 应用来说，也要严格区分，毕竟这是跟应用大小相关的东西。还是严格一点好。</p></blockquote><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>本章节的重点从 electron 的打包体积优化逐步变成 node_modules 的体积优化，再演变为 <code>dependencies</code> 与 <code>devDependencies</code> 的区别，通过实验验证心中所存在的疑惑。</p><p>如果对本章节存在疑问，欢迎在评论区留言。如果觉得阿宽哪里表达错误，可指出，虚心请教～</p>',54)])])}const C=a(m,[["render",f]]);export{D as __pageData,C as default};
